<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Avisos privados da empresa';require APPPATH.'views/admin/includes/native_company_layout_head.php';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'settings/pusher');$hidden=function($action)use($csrf,$profile,$descriptor,$esc){echo '<input type="hidden" name="company_pusher_csrf" value="'.$esc($csrf).'"><input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="revision" value="'.$esc($profile['revision']??$descriptor['revision']??0).'">';};?>
<section class="company-settings-card"><h1>Avisos privados por Pusher</h1><p>Perfil próprio da empresa. O canal recebe apenas um pulso vazio; os detalhes da tarefa vêm deste leitor autenticado, com autorização atual. Aceitação pela API não confirma leitura ou entrega ao navegador.</p><?php if($error){?><p role="alert"><?= $esc($error); ?></p><?php }?>
<?php if($profile){?><p>Estado local: <strong id="pusher-profile-status"><?= $esc(['unconfigured'=>'Não configurado','enabled'=>'Ativado localmente','revoked'=>'Revogado'][$profile['status']]??'Indisponível'); ?></strong>. Esta página não verifica credenciais no provedor.</p><?php }if($can_configure&&$profile){?>
<?= form_open($url,['id'=>'pusher-profile-form']);$hidden('save'); ?><label>ID do aplicativo próprio<input class="form-control" name="app_id" value="<?= $esc($profile['app_id']); ?>" maxlength="20" required></label><label>Chave pública do aplicativo<input class="form-control" name="app_key" value="<?= $esc($profile['app_key']); ?>" maxlength="80" required></label><label>Cluster<select class="form-control" name="cluster"><?php foreach(CompanyPusherProfile::CLUSTERS as$cluster){?><option value="<?= $esc($cluster); ?>" <?= $profile['cluster']===$cluster?'selected':''; ?>><?= $esc($cluster); ?></option><?php }?></select></label><label>Segredo próprio<input class="form-control" type="password" name="app_secret" value="" maxlength="4096" autocomplete="new-password"></label><p><?= $profile['secret_configured']?'Segredo protegido; vazio preserva apenas o mesmo aplicativo e cluster.':'Informe o segredo do próprio aplicativo.'; ?> Salvar muda a revisão e invalida filas/canais anteriores. Não há herança das chaves globais.</p><button type="submit">Salvar e ativar perfil local</button><?= form_close(); ?><?php if($profile['revision']){?><?= form_open($url,['id'=>'pusher-revoke-form']);$hidden('revoke'); ?><button type="submit">Revogar perfil local</button><?= form_close(); ?><?php }} ?>
<h2>Avisos de tarefas atribuídas a você</h2><p id="pusher-live-status" role="status">Conexão remota desligada nesta aba. A leitura manual também usa a fonte própria autorizada.</p><?php if($descriptor){?><?= form_open($url,['id'=>'pusher-channel-proof','hidden'=>'hidden']);$hidden('authorize');echo form_close(); ?><button type="button" id="pusher-start">Conectar canal privado nesta aba</button><button type="button" id="pusher-stop" disabled>Desconectar esta aba</button><button type="button" id="pusher-refresh">Atualizar avisos próprios</button><?php }?><ul id="pusher-own-inbox"><?php foreach($inbox as$item){?><li><?= $esc($item['name']); ?> — <?= $esc($item['created_at']); ?> UTC</li><?php }?></ul>
<?php if($activity['publish']&&$descriptor){?><h2>Enfileirar aviso ao responsável atual</h2><p>Selecione a tarefa própria. O responsável e o conteúdo são determinados pela fonte atual; não há destinatário, canal ou texto livre.</p><?php foreach($activity['tasks']as$task){?><?= form_open($url,['class'=>'pusher-task-queue']);$hidden('queue'); ?><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><input type="hidden" name="task_id" value="<?= (int)$task['id']; ?>"><input type="hidden" name="task_revision" value="<?= (int)$task['revision']; ?>"><span><?= $esc($task['name']); ?></span> <button type="submit">Enfileirar aviso próprio</button><?= form_close(); ?><?php }?><?php }?>
<h2>Suas tentativas nesta empresa</h2><table class="table"><thead><tr><th>Data</th><th>Resultado local</th><th>Ação</th></tr></thead><tbody><?php foreach($activity['notices']as$n){?><tr data-pusher-key="<?= $esc($n['request_key']); ?>"><td><?= $esc($n['created_at']); ?> UTC</td><td class="pusher-notice-status"><?= $esc(['blocked'=>'Bloqueado antes da tentativa; reabra a fonte','pending'=>'Enfileirado; sem tentativa','submitting'=>'Tentativa em andamento ou sem confirmação','accepted'=>'Aceito pela API; entrega não comprovada','uncertain'=>'Resultado incerto; não repetir automaticamente'][$n['status']]??'Indisponível'); ?></td><td><?php if($n['status']==='pending'&&$descriptor&&$activity['publish']){?><?= form_open($url,['class'=>'pusher-task-dispatch']);$hidden('dispatch'); ?><input type="hidden" name="request_key" value="<?= $esc($n['request_key']); ?>"><button type="submit">Tentar pulso privado</button><?= form_close(); ?><?php }?></td></tr><?php }?></tbody></table><p>Revogar bloqueia novas assinaturas, a fila e o leitor. Uma assinatura remota já aberta pode continuar conectada até o cliente encerrar; nenhum detalhe é transmitido no canal, e os leitores continuam sujeitos à autorização atual. Não há promessa de encerramento remoto instantâneo.</p></section>
<?php if($descriptor){?><script src="<?= $esc(base_url('assets/company_pusher/pusher-8.3.0.368a455b2523.min.js')); ?>"></script><script>
(function(){'use strict';const config=<?= json_encode($descriptor,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR); ?>,url=<?= json_encode($url,JSON_HEX_TAG|JSON_THROW_ON_ERROR); ?>,csrf=<?= json_encode($csrf,JSON_THROW_ON_ERROR); ?>,context=<?= json_encode(CompanyRequestScope::token(),JSON_THROW_ON_ERROR); ?>,status=document.getElementById('pusher-live-status'),list=document.getElementById('pusher-own-inbox'),start=document.getElementById('pusher-start'),stop=document.getElementById('pusher-stop');let client=null,loading=false;function disconnect(){if(client){client.disconnect();client=null;}start.disabled=false;stop.disabled=true;status.textContent='Canal privado desconectado nesta aba.';}async function read(){if(loading)return;loading=true;try{const response=await fetch(url+'?reader=1',{credentials:'same-origin',headers:{'X-Company-Context':context}});if(!response.ok)throw new Error();const data=await response.json();list.replaceChildren();for(const item of data.items){const li=document.createElement('li');li.textContent=item.name+' — '+item.created_at+' UTC';list.appendChild(li);}status.textContent='Leitor próprio atualizado; entrega remota não é comprovada.';}catch(e){list.replaceChildren();disconnect();status.textContent='Leitura negada ou contexto alterado. Reabra a empresa.';}finally{loading=false;}}start.addEventListener('click',function(){disconnect();if(typeof Pusher==='undefined'){status.textContent='Biblioteca local indisponível.';return;}start.disabled=true;stop.disabled=false;status.textContent='Conectando canal privado da empresa…';client=new Pusher(config.app_key,{cluster:config.cluster,forceTLS:true,enabledTransports:['ws'],disableStats:true,channelAuthorization:{customHandler:async function(params,callback){try{const form=new URLSearchParams(new FormData(document.getElementById('pusher-channel-proof')));form.set('channel_name',params.channelName);form.set('socket_id',params.socketId);const response=await fetch(url,{method:'POST',body:form,credentials:'same-origin'});if(!response.ok)throw new Error();callback(null,await response.json());}catch(e){disconnect();callback(new Error('Assinatura privada negada'),null);}}}});const channel=client.subscribe(config.channel);channel.bind('company-task-pulse',read);channel.bind('pusher:subscription_succeeded',function(){status.textContent='Canal privado conectado; cada leitura revalida seu acesso.';});channel.bind('pusher:subscription_error',disconnect);});stop.addEventListener('click',disconnect);document.getElementById('pusher-refresh').addEventListener('click',read);window.addEventListener('pagehide',disconnect,{once:true});})();
</script><?php }require APPPATH.'views/admin/includes/native_company_layout_tail.php'; ?>
